import{bV as s,aL as n,u as e,G as i}from"./chunks/framework.DvBUyM1S.js";const m=JSON.parse('{"title":"Mac终端替代工具iTerm2","description":"","frontmatter":{"title":"Mac终端替代工具iTerm2","date":"2018-12-28T00:00:00.000Z","tags":["Mac"],"permalink":"/pages/46ba7f/","categories":[null]},"headers":[],"relativePath":"06.工具/03.Mac/03.Mac终端替代工具iTerm2.md","filePath":"06.工具/03.Mac/03.Mac终端替代工具iTerm2.md","lastUpdated":1652231681000}'),p={name:"06.工具/03.Mac/03.Mac终端替代工具iTerm2.md"};function l(t,a,r,c,o,h){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="mac终端替代工具iterm2" tabindex="-1">Mac终端替代工具iTerm2 <a class="header-anchor" href="#mac终端替代工具iterm2" aria-label="Permalink to &quot;Mac终端替代工具iTerm2&quot;">​</a></h1><h2 id="什么是iterm2" tabindex="-1">什么是iTerm2？ <a class="header-anchor" href="#什么是iterm2" aria-label="Permalink to &quot;什么是iTerm2？&quot;">​</a></h2><p>iTerm2是Terminal的替代品，是iTerm的后继产品。它适用于MacOS 10.12或更高版本的Mac。iTerm2将终端带入了您从未想过一直想要的功能，使其进入了现代时代。</p><p><strong>效果</strong></p><p><img src="https://cloud.githubusercontent.com/assets/2618447/6316862/70f58fb6-ba03-11e4-82c9-c083bf9a6574.png" alt="cloud" loading="lazy"></p><h3 id="一、item2软件下载" tabindex="-1">一、item2软件下载 <a class="header-anchor" href="#一、item2软件下载" aria-label="Permalink to &quot;一、item2软件下载&quot;">​</a></h3><p><a href="https://www.iterm2.com/" target="_blank" rel="noreferrer">item2官网</a></p><p>我上传到蓝奏云，下载速度还不错。<a href="https://qqlcx5.lanzous.com/ibyghcf" target="_blank" rel="noreferrer">前往蓝奏云下载</a></p><blockquote><p>如果下载以下资源下不下来，可以尝试梯子配<code>Proxifier</code>就可以走VPS通道。</p></blockquote><h3 id="配置-oh-my-zsh" tabindex="-1">配置 Oh My Zsh <a class="header-anchor" href="#配置-oh-my-zsh" aria-label="Permalink to &quot;配置 Oh My Zsh&quot;">​</a></h3><p><a href="http://ohmyz.sh/" target="_blank" rel="noreferrer">Oh My Zsh</a> 是一款社区驱动的命令行工具，正如它的主页上说的，Oh My Zsh 是一种生活方式。它基于zsh命令行，提供了主题配置，插件机制，已经内置的便捷操作。给我们一种全新的方式使用命令行。</p><p><strong>安装</strong></p><ol><li>官网推荐安装方式：</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一种 curl:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sh -c &quot;$(curl -fsSL https://raw.github.com/ohmyzsh/ohmyzsh/master/tools/install.sh)&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二种 wget:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sh -c &quot;$(wget https://raw.github.com/ohmyzsh/ohmyzsh/master/tools/install.sh -O -)&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>安装好之后，需要把 Zsh 设置为当前用户的默认 Shell</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ chsh -s /bin/zsh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后，将主题修改为ZSH_THEME=&quot;agnoster&quot;</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ vim ~/.zshrc</span></span>
<span class="line"><span>输入i进入编辑模式,将ZSH_THEME=&quot;&quot;编辑为ZSH_THEME=&quot;agnoster&quot;</span></span>
<span class="line"><span>按下esc键,退出编辑,</span></span>
<span class="line"><span>:wq保存退出</span></span>
<span class="line"><span>修改成功!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.2/img/20200725002842.jpg" alt="agnoster" loading="lazy"></p><p>上面效果主题为<code>agnoster</code>，不喜欢可以选择其他主题 <a href="https://github.com/ohmyzsh/ohmyzsh/wiki/Themes" target="_blank" rel="noreferrer">Oh My Zsh</a></p><h3 id="配置-meslo-字体" tabindex="-1">配置 Meslo 字体 <a class="header-anchor" href="#配置-meslo-字体" aria-label="Permalink to &quot;配置 Meslo 字体&quot;">​</a></h3><ol><li><p>字体文件下载 <a href="https://qqlcx5.lanzous.com/ibzub5c" target="_blank" rel="noreferrer">蓝奏云</a></p></li><li><p>然后打开安装后，选中item2软件，按<code>Command + ,</code>键，打开 <code>Preferences</code> 配置界面，然后<code>Profiles -&gt; Text -&gt; Font -&gt; Chanage Font</code>，选择 <code>Meslo LG M Regular for Powerline</code> 字体。</p></li><li><p>小提示，字体必须安装，不然一些特殊字符会出现乱码</p></li></ol><p>如图所示</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.2/img/20200725002848.jpg" alt="-w930" loading="lazy"></p><h3 id="iterm2-快捷命令" tabindex="-1">iTerm2 快捷命令 <a class="header-anchor" href="#iterm2-快捷命令" aria-label="Permalink to &quot;iTerm2 快捷命令&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command + t 新建标签</span></span>
<span class="line"><span>command + w 关闭标签</span></span>
<span class="line"><span>command + 数字 command + 左右方向键    切换标签</span></span>
<span class="line"><span>command + enter 切换全屏</span></span>
<span class="line"><span>command + f 查找</span></span>
<span class="line"><span>command + d 水平分屏</span></span>
<span class="line"><span>command + shift + d 垂直分屏</span></span>
<span class="line"><span>command + option + 方向键 command + [ 或 command + ]    切换屏幕</span></span>
<span class="line"><span>command + ; 查看历史命令</span></span>
<span class="line"><span>command + shift + h 查看剪贴板历史</span></span>
<span class="line"><span>ctrl + u    清除当前行</span></span>
<span class="line"><span>ctrl + l    清屏</span></span>
<span class="line"><span>ctrl + a    到行首</span></span>
<span class="line"><span>ctrl + e    到行尾</span></span>
<span class="line"><span>ctrl + f/b  前进后退</span></span>
<span class="line"><span>ctrl + p    上一条命令</span></span>
<span class="line"><span>ctrl + r    搜索命令历史</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h2 id="以下按需加载" tabindex="-1">以下按需加载 <a class="header-anchor" href="#以下按需加载" aria-label="Permalink to &quot;以下按需加载&quot;">​</a></h2><h3 id="配置-iterm2-主题" tabindex="-1">配置 iTerm2 主题 <a class="header-anchor" href="#配置-iterm2-主题" aria-label="Permalink to &quot;配置 iTerm2 主题&quot;">​</a></h3><p>选中item2软件，按<code>Command + ,</code>键，打开 <code>Preferences</code> 配置界面，然后<code>Profiles -&gt; Colors</code> 选择 <code>Solarized Dark</code> 主题。</p><p>按图中所示操作</p><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.2/img/20200725002854.jpg" alt="-w929" loading="lazy"></p><h2 id="推荐插件" tabindex="-1">推荐插件 <a class="header-anchor" href="#推荐插件" aria-label="Permalink to &quot;推荐插件&quot;">​</a></h2><h3 id="zsh-autosuggestions" tabindex="-1">zsh-autosuggestions <a class="header-anchor" href="#zsh-autosuggestions" aria-label="Permalink to &quot;zsh-autosuggestions&quot;">​</a></h3><p>它是Oh-myszh的一个插件，作用基本上是根据历史输入指令的记录即时的提示，能够很大的提高效率。</p><p>1.克隆到插件目录:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone git://github.com/zsh-users/zsh-autosuggestions</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>2.vim ~/.zshrc</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins=(git zsh-autosuggestions)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://cdn.jsdelivr.net/gh/qqlcx5/figure-bed@1.2/img/20200725002851.jpg" alt="-w482" loading="lazy"></p><h3 id="zsh-syntax-highlighting" tabindex="-1">zsh-syntax-highlighting <a class="header-anchor" href="#zsh-syntax-highlighting" aria-label="Permalink to &quot;zsh-syntax-highlighting&quot;">​</a></h3><p>这是一个命令高亮插件，输入为绿色时表示可用命令，路径带有下划线时表示可用路径</p><p>1.克隆到插件目录：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/zsh-users/zsh-syntax-highlighting.git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>2.复制到终端回车键</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;source \${(q-)PWD}/zsh-syntax-highlighting/zsh-syntax-highlighting.zsh&quot; &gt;&gt; \${ZDOTDIR:-$HOME}/.zshrc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>3.配置生效</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source .zshrc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="iterm2-隐藏用户名和主机名" tabindex="-1">iTerm2 隐藏用户名和主机名 <a class="header-anchor" href="#iterm2-隐藏用户名和主机名" aria-label="Permalink to &quot;iTerm2 隐藏用户名和主机名&quot;">​</a></h3><ol><li>vim ~/.zshrc</li><li>在底部新增 DEFAULT_USER=&quot;电脑用户名&quot;</li></ol><p>不知道自己电脑用户名的,在终端输入whoami，输出用户名</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ whoami</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,51)])])}const u=s(p,[["render",l]]);export{m as __pageData,u as default};
